import React, { useState, useRef, useCallback, useEffect } from 'react';
import Webcam from 'react-webcam';
import { attendanceAPI } from './api_service';

const CameraRecognition = () => {
  const webcamRef = useRef(null);
  const [loading, setLoading] = useState(false);
  const [displayMessage, setDisplayMessage] = useState('');   // Une seule string pour tout
  const [isSuccess, setIsSuccess] = useState(false);
  const [autoMode, setAutoMode] = useState(false);

  const videoConstraints = {
    width: 1280,
    height: 720,
    facingMode: "user"
  };

  const handleCapture = useCallback(async () => {
    if (!webcamRef.current) return;

    setLoading(true);
    setDisplayMessage('');
    setIsSuccess(false);

    try {
      const imageSrc = webcamRef.current.getScreenshot();
      if (!imageSrc) throw new Error("Impossible de capturer l'image");

      const response = await attendanceAPI.recognize(imageSrc);
      const data = response?.data || response || {};

      console.log("🔍 API RAW RESPONSE:", response);
      console.log("📊 DATA reçue:", data);

      const name = String(data.student || data.student_name || data.name || "Inconnu");
      const confidence = Number(data.confidence || 0) * 100;

      if (data.success || data.student || confidence > 0) {
        setDisplayMessage(`✅ ${name} - Confiance : ${confidence.toFixed(1)}%`);
        setIsSuccess(true);
      } else {
        setDisplayMessage(String(data.message || data.error || "Visage non reconnu"));
        setIsSuccess(false);
      }

    } catch (err) {
      const errorMsg = err.response?.data?.error 
                    || err.response?.data?.message 
                    || err.message 
                    || "Erreur de connexion au serveur";

      console.error("❌ Erreur reconnaissance :", err);
      setDisplayMessage(String(errorMsg));
      setIsSuccess(false);
    } finally {
      setLoading(false);
    }
  }, []);

  // Auto mode
  useEffect(() => {
    let interval = null;
    if (autoMode && !loading) {
      interval = setInterval(handleCapture, 5000);
    }
    return () => {
      if (interval) clearInterval(interval);
    };
  }, [autoMode, loading, handleCapture]);

  return (
    <div style={{ padding: '30px', maxWidth: '700px', margin: '0 auto', fontFamily: 'system-ui' }}>
      <h2 style={{ textAlign: 'center', marginBottom: '20px' }}>📷 Reconnaissance Faciale</h2>

      <div style={{ position: 'relative', borderRadius: '12px', overflow: 'hidden', background: '#000', marginBottom: '20px' }}>
        <Webcam
          ref={webcamRef}
          audio={false}
          screenshotFormat="image/jpeg"
          videoConstraints={videoConstraints}
          style={{ width: '100%', height: 'auto', display: 'block' }}
        />
        {loading && (
          <div style={{
            position: 'absolute',
            inset: 0,
            background: 'rgba(0,0,0,0.8)',
            color: '#fff',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            fontSize: '22px',
            fontWeight: 'bold'
          }}>
            ⏳ Analyse IA en cours...
          </div>
        )}
      </div>

      <div style={{ display: 'flex', gap: '15px', marginBottom: '30px' }}>
        <button 
          onClick={handleCapture}
          disabled={loading || autoMode}
          style={{
            flex: 1,
            padding: '14px',
            fontSize: '16px',
            background: loading || autoMode ? '#6b7280' : '#4F46E5',
            color: 'white',
            border: 'none',
            borderRadius: '8px',
            cursor: loading || autoMode ? 'not-allowed' : 'pointer'
          }}
        >
          {loading ? '⏳ Traitement...' : '🔍 Scan Manuel'}
        </button>

        <button 
          onClick={() => setAutoMode(!autoMode)}
          style={{
            flex: 1,
            padding: '14px',
            fontSize: '16px',
            background: autoMode ? '#EF4444' : '#10B981',
            color: 'white',
            border: 'none',
            borderRadius: '8px',
            cursor: 'pointer'
          }}
        >
          {autoMode ? '⏹ STOP AUTO SCAN' : '🔄 Lancer Auto Scan'}
        </button>
      </div>

      {/* Affichage résultat - TOUT en string */}
      {displayMessage && (
        <div style={{
          padding: '20px',
          borderRadius: '12px',
          backgroundColor: isSuccess ? '#DCFCE7' : '#FEE2E2',
          color: isSuccess ? '#166534' : '#991B1B',
          fontSize: '18px',
          fontWeight: '500',
          textAlign: 'center',
          border: isSuccess ? '2px solid #86EFAC' : '2px solid #FECACA'
        }}>
          {displayMessage}
        </div>
      )}

      {!displayMessage && !loading && (
        <p style={{ textAlign: 'center', color: '#64748B', marginTop: '20px' }}>
          Appuyez sur "Scan Manuel" pour tester la reconnaissance
        </p>
      )}
    </div>
  );
};

export default CameraRecognition;
